import random

def regles (mot_u, reponse) :
    """
    Il prend comme parametres le mot choisit par le cpu 
    et le mot entré par le joueur
    Il applique les regles du jeu et renvoie le boolean "gagne"
    gagne est false si le jouer n'a pas encore trouvé le mot
    true pour le cas contraire.

    """
    couleurs = {'reset' : '\033[0m', 'bleu' : '\033[1;34m', 'vert' : '\033[1;32m'}
    pos = 0
    gagne = False
    dictionnaire = dictionnaire_lettres(reponse)
    if mot_u == reponse :
        gagne = True 
        
    for lettre in mot_u :
        if lettre == reponse [pos] and dictionnaire [lettre] != 0 :
            dictionnaire [lettre] -= 1
            print (f"{couleurs ['vert']}{lettre}{couleurs ['reset']}", end = '')
        elif lettre in reponse and dictionnaire [lettre] != 0 : 
            dictionnaire [lettre] -= 1
            print (f"{couleurs ['bleu']}{lettre}{couleurs ['reset']}", end = '')
        else :
            print (f"{lettre}", end = '')
        pos += 1
        
    return gagne

def choix_de_mot(liste):
    """ choisit un mot aléatoirement dans une liste de mot 
        et le retourne 
    """
    nombre = random.randint(1,len(liste) - 1)
    # "nombre: est le nombre de le mot dans la liste. Le mot qu'on a besoin decouvrir"
    
    mot = liste[nombre]
    # mot: est le mot que nous recherchons
    
    return mot


def dictionnaire_lettres (reponse) :
    """ Crée un dictionnaire des lettres dans la réponse 
        avec leur nombre d'appartions dans la réponse
    """
    dictionnaire = {}
    for lettre in reponse :
        dictionnaire [lettre] = dictionnaire.get(lettre, 0) + 1
    return dictionnaire
    
def verif_longueur (mot_u, reponse) : 
    """
    Je test si le mot rentré est de la même 
    longueur que la réponse

    """
    long_ok = True
    if len(mot_u) != len(reponse) :
        print (f"Veuyez écrir un mon de {len(reponse)} lettres")
        long_ok = False
    return long_ok

def choix_langue (liste_5lettres_fr, liste_5lettres_eng, mot_5_br, mot_5_es, choix) :
    """  Retourne la liste choisit selon la langue de l'utilisateur
    """
    liste = []
    choix = choix.upper()
    if choix == "FRANCAIS" or choix == "FRANÇAIS" or choix == "FRENCH" :
        liste = liste_5lettres_fr
    elif choix == "ANGLAIS" or choix == "ENGLISH" :
        liste = liste_5lettres_eng
    elif choix == "ESPAGNOL" or choix == "ESPANOL" or choix == "ESPAÑOL" :
        liste = mot_5_es
    elif choix == "PORTUGAIS" or choix == "PORTUGUES" or choix == "PORTUGÛES" :
        liste = mot_5_br
    else :
        print ("Mauvaise saisie, ecrivez correctement français ou anglais")
    return liste

def majuscule(liste):
    """ Prends une liste et la renvoie en ,ajuscule
    """
    for mot in range(len(liste)):
        liste[mot] = liste[mot].upper()
    return liste


